import gurobipy as gp
from gurobipy import GRB
areas = []
values = {}
weights = {}
capacity = None
for rec in LEGACY_RECORDS:
    if rec['source'].endswith('capacity.csv'):
        cap_val = rec['values'].get('Capacity')
        if cap_val is not None:
            capacity = int(cap_val)
    elif rec['source'].endswith('products.csv'):
        area = rec['values']['ProductName']
        areas.append(area)
        values[area] = int(rec['values']['Value'])
        weights[area] = int(rec['values']['Weight'])
if capacity is None:
    raise ValueError('Missing development capacity in LEGACY_RECORDS')
if set(areas) != set(values.keys()) or set(areas) != set(weights.keys()):
    raise ValueError('Mismatch in area identifiers and coefficients')
m = gp.Model('NYC_Development')
x_vars = m.addVars(areas, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[a] * x_vars[a] for a in areas)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weights[a] * x_vars[a] for a in areas)) <= capacity, name='capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in x_vars.values():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')